    31→// WriteCommitted writes a committed checkpoint to the entire/sessions branch.
    32→// Checkpoints are stored at sharded paths: <id[:2]>/<id[2:]>/
    33→//
    34→// For task checkpoints (IsTask=true), additional files are written under tasks/<tool-use-id>/:
    35→//   - For incremental checkpoints: checkpoints/NNN-<tool-use-id>.json
    36→//   - For final checkpoints: checkpoint.json and agent-<agent-id>.jsonl
    37→func (s *GitStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
    38→	_ = ctx // Reserved for future use
    39→
    40→	// Validate identifiers to prevent path traversal and malformed data
    41→	if opts.CheckpointID.IsEmpty() {
    42→		return errors.New("invalid checkpoint options: checkpoint ID is required")
    43→	}
    44→	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
    45→		return fmt.Errorf("invalid checkpoint options: %w", err)
    46→	}
    47→	if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
    48→		return fmt.Errorf("invalid checkpoint options: %w", err)
    49→	}
    50→	if err := validation.ValidateAgentID(opts.AgentID); err != nil {
    51→		return fmt.Errorf("invalid checkpoint options: %w", err)
    52→	}
    53→
    54→	// Ensure sessions branch exists
    55→	if err := s.ensureSessionsBranch(); err != nil {
    56→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
    57→	}
    58→
    59→	// Get current branch tip and flatten tree
    60→	ref, entries, err := s.getSessionsBranchEntries()
    61→	if err != nil {
    62→		return err
    63→	}
    64→
    65→	// Use sharded path: <id[:2]>/<id[2:]>/
    66→	basePath := opts.CheckpointID.Path() + "/"
    67→
    68→	// Track task metadata path for commit trailer
    69→	var taskMetadataPath string
    70→
    71→	// Handle task checkpoints
    72→	if opts.IsTask && opts.ToolUseID != "" {
    73→		taskMetadataPath, err = s.writeTaskCheckpointEntries(opts, basePath, entries)
    74→		if err != nil {
    75→			return err
    76→		}
    77→	}
    78→
    79→	// Write standard checkpoint entries (transcript, prompts, context, metadata)
    80→	if err := s.writeStandardCheckpointEntries(opts, basePath, entries); err != nil {
    81→		return err
    82→	}
    83→
    84→	// Build and commit
    85→	newTreeHash, err := BuildTreeFromEntries(s.repo, entries)
    86→	if err != nil {
    87→		return err
    88→	}
    89→
    90→	commitMsg := s.buildCommitMessage(opts, taskMetadataPath)
    91→	newCommitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, opts.AuthorName, opts.AuthorEmail)
    92→	if err != nil {
    93→		return err
    94→	}
    95→
    96→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
    97→	newRef := plumbing.NewHashReference(refName, newCommitHash)
    98→	if err := s.repo.Storer.SetReference(newRef); err != nil {
    99→		return fmt.Errorf("failed to set branch reference: %w", err)
   100→	}
   101→
   102→	return nil
   103→}
