   105→// getSessionsBranchEntries returns the sessions branch reference and flattened tree entries.
   106→func (s *GitStore) getSessionsBranchEntries() (*plumbing.Reference, map[string]object.TreeEntry, error) {
   107→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   108→	ref, err := s.repo.Reference(refName, true)
   109→	if err != nil {
   110→		return nil, nil, fmt.Errorf("failed to get sessions branch reference: %w", err)
   111→	}
   112→
   113→	parentCommit, err := s.repo.CommitObject(ref.Hash())
   114→	if err != nil {
   115→		return nil, nil, fmt.Errorf("failed to get commit object: %w", err)
   116→	}
   117→
   118→	baseTree, err := parentCommit.Tree()
   119→	if err != nil {
   120→		return nil, nil, fmt.Errorf("failed to get commit tree: %w", err)
   121→	}
   122→
   123→	entries := make(map[string]object.TreeEntry)
   124→	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
   125→		return nil, nil, err
   126→	}
   127→
   128→	return ref, entries, nil
   129→}
