   404→// mergeFilesTouched combines two file lists, removing duplicates.
   405→func mergeFilesTouched(existing, additional []string) []string {
   406→	seen := make(map[string]bool)
   407→	var result []string
   408→
   409→	for _, f := range existing {
   410→		if !seen[f] {
   411→			seen[f] = true
   412→			result = append(result, f)
   413→		}
   414→	}
   415→	for _, f := range additional {
   416→		if !seen[f] {
   417→			seen[f] = true
   418→			result = append(result, f)
   419→		}
   420→	}
   421→
   422→	sort.Strings(result)
   423→	return result
   424→}
