   570→// buildCommitMessage constructs the commit message with proper trailers.
   571→// The commit subject is always "Checkpoint: <id>" for consistency.
   572→// If CommitSubject is provided (e.g., for task checkpoints), it's included in the body.
   573→func (s *GitStore) buildCommitMessage(opts WriteCommittedOptions, taskMetadataPath string) string {
   574→	var commitMsg strings.Builder
   575→
   576→	// Subject line is always the checkpoint ID for consistent formatting
   577→	commitMsg.WriteString(fmt.Sprintf("Checkpoint: %s\n\n", opts.CheckpointID))
   578→
   579→	// Include custom description in body if provided (e.g., task checkpoint details)
   580→	if opts.CommitSubject != "" {
   581→		commitMsg.WriteString(opts.CommitSubject + "\n\n")
   582→	}
   583→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.SessionTrailerKey, opts.SessionID))
   584→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.StrategyTrailerKey, opts.Strategy))
   585→	if opts.Agent != "" {
   586→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.AgentTrailerKey, opts.Agent))
   587→	}
   588→	if opts.EphemeralBranch != "" {
   589→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.EphemeralBranchTrailerKey, opts.EphemeralBranch))
   590→	}
   591→	if taskMetadataPath != "" {
   592→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.MetadataTaskTrailerKey, taskMetadataPath))
   593→	}
   594→
   595→	return commitMsg.String()
   596→}
