   616→// ReadCommitted reads a committed checkpoint by ID from the entire/sessions branch.
   617→// Returns nil, nil if the checkpoint doesn't exist.
   618→//
   619→
   620→func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*ReadCommittedResult, error) {
   621→	_ = ctx // Reserved for future use
   622→
   623→	tree, err := s.getSessionsBranchTree()
   624→	if err != nil {
   625→		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
   626→	}
   627→
   628→	checkpointPath := checkpointID.Path()
   629→	checkpointTree, err := tree.Tree(checkpointPath)
   630→	if err != nil {
   631→		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
   632→	}
   633→
   634→	result := &ReadCommittedResult{}
   635→
   636→	// Read metadata.json
   637→	if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   638→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
   639→			//nolint:errcheck,gosec // Best-effort parsing, defaults are fine
   640→			json.Unmarshal([]byte(content), &result.Metadata)
   641→		}
   642→	}
   643→
   644→	// Read transcript (handles both chunked and non-chunked formats)
   645→	if transcript, err := readTranscriptFromTree(checkpointTree, result.Metadata.Agent); err == nil && transcript != nil {
   646→		result.Transcript = transcript
   647→	}
   648→
   649→	// Read prompts
   650→	if file, fileErr := checkpointTree.File(paths.PromptFileName); fileErr == nil {
   651→		if content, contentErr := file.Contents(); contentErr == nil {
   652→			result.Prompts = content
   653→		}
   654→	}
   655→
   656→	// Read context
   657→	if file, fileErr := checkpointTree.File(paths.ContextFileName); fileErr == nil {
   658→		if content, contentErr := file.Contents(); contentErr == nil {
   659→			result.Context = content
   660→		}
   661→	}
   662→
   663→	// Read archived sessions if this is a multi-session checkpoint
   664→	if result.Metadata.SessionCount > 1 {
   665→		result.ArchivedSessions = s.readArchivedSessions(checkpointTree, result.Metadata.SessionCount, result.Metadata.Agent)
   666→	}
   667→
   668→	return result, nil
   669→}
