   671→// ListCommitted lists all committed checkpoints from the entire/sessions branch.
   672→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
   673→//
   674→
   675→func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
   676→	_ = ctx // Reserved for future use
   677→
   678→	tree, err := s.getSessionsBranchTree()
   679→	if err != nil {
   680→		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
   681→	}
   682→
   683→	var checkpoints []CommittedInfo
   684→
   685→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
   686→	for _, bucketEntry := range tree.Entries {
   687→		if bucketEntry.Mode != filemode.Dir {
   688→			continue
   689→		}
   690→		// Bucket should be 2 hex chars
   691→		if len(bucketEntry.Name) != 2 {
   692→			continue
   693→		}
   694→
   695→		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
   696→		if treeErr != nil {
   697→			continue
   698→		}
   699→
   700→		// Each entry in the bucket is the remaining part of the checkpoint ID
   701→		for _, checkpointEntry := range bucketTree.Entries {
   702→			if checkpointEntry.Mode != filemode.Dir {
   703→				continue
   704→			}
   705→
   706→			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
   707→			if cpTreeErr != nil {
   708→				continue
   709→			}
   710→
   711→			// Reconstruct checkpoint ID: <bucket><remaining>
   712→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
   713→			checkpointID, cpIDErr := id.NewCheckpointID(checkpointIDStr)
   714→			if cpIDErr != nil {
   715→				// Skip invalid checkpoint IDs (shouldn't happen with our own data)
   716→				continue
   717→			}
   718→
   719→			info := CommittedInfo{
   720→				CheckpointID: checkpointID,
   721→			}
   722→
   723→			// Get details from metadata file
   724→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   725→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
   726→					var metadata CommittedMetadata
   727→					if err := json.Unmarshal([]byte(content), &metadata); err == nil {
   728→						info.SessionID = metadata.SessionID
   729→						info.CreatedAt = metadata.CreatedAt
   730→						info.CheckpointsCount = metadata.CheckpointsCount
   731→						info.FilesTouched = metadata.FilesTouched
   732→						info.Agent = metadata.Agent
   733→						info.IsTask = metadata.IsTask
   734→						info.ToolUseID = metadata.ToolUseID
   735→						info.SessionCount = metadata.SessionCount
   736→						info.SessionIDs = metadata.SessionIDs
   737→					}
   738→				}
   739→			}
   740→
   741→			checkpoints = append(checkpoints, info)
   742→		}
   743→	}
   744→
   745→	// Sort by time (most recent first)
   746→	sort.Slice(checkpoints, func(i, j int) bool {
   747→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
   748→	})
   749→
   750→	return checkpoints, nil
   751→}
