   753→// GetTranscript retrieves the transcript for a specific checkpoint ID.
   754→func (s *GitStore) GetTranscript(ctx context.Context, checkpointID id.CheckpointID) ([]byte, error) {
   755→	result, err := s.ReadCommitted(ctx, checkpointID)
   756→	if err != nil {
   757→		return nil, err
   758→	}
   759→	if result == nil {
   760→		return nil, fmt.Errorf("checkpoint not found: %s", checkpointID)
   761→	}
   762→	if len(result.Transcript) == 0 {
   763→		return nil, fmt.Errorf("no transcript found for checkpoint: %s", checkpointID)
   764→	}
   765→	return result.Transcript, nil
   766→}
