   769→// This is the primary method for looking up session logs by checkpoint ID.
   770→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
   771→// Returns ErrNoTranscript if the checkpoint exists but has no transcript.
   772→func (s *GitStore) GetSessionLog(cpID id.CheckpointID) ([]byte, string, error) {
   773→	result, err := s.ReadCommitted(context.Background(), cpID)
