   800→// UpdateSummary updates the summary field in an existing checkpoint's metadata.
   801→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
   802→func (s *GitStore) UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
   803→	_ = ctx // Reserved for future use
   804→
   805→	// Ensure sessions branch exists
   806→	if err := s.ensureSessionsBranch(); err != nil {
   807→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
   808→	}
   809→
   810→	// Get current branch tip and flatten tree
   811→	ref, entries, err := s.getSessionsBranchEntries()
   812→	if err != nil {
   813→		return err
   814→	}
   815→
   816→	// Read existing metadata
   817→	basePath := checkpointID.Path() + "/"
   818→	metadataPath := basePath + paths.MetadataFileName
   819→	entry, exists := entries[metadataPath]
   820→	if !exists {
   821→		return ErrCheckpointNotFound
   822→	}
   823→
   824→	// Read and parse existing metadata
   825→	existingMetadata, err := s.readMetadataFromBlob(entry.Hash)
   826→	if err != nil {
   827→		return fmt.Errorf("failed to read existing metadata: %w", err)
   828→	}
   829→
   830→	// Update the summary
   831→	existingMetadata.Summary = summary
   832→
   833→	// Write updated metadata
   834→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(existingMetadata, "", "  ")
   835→	if err != nil {
   836→		return fmt.Errorf("failed to marshal metadata: %w", err)
   837→	}
   838→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
   839→	if err != nil {
   840→		return fmt.Errorf("failed to create metadata blob: %w", err)
   841→	}
   842→	entries[metadataPath] = object.TreeEntry{
   843→		Name: metadataPath,
   844→		Mode: filemode.Regular,
   845→		Hash: metadataHash,
   846→	}
   847→
   848→	// Build and commit
   849→	newTreeHash, err := BuildTreeFromEntries(s.repo, entries)
   850→	if err != nil {
   851→		return err
   852→	}
   853→
   854→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
   855→	commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", checkpointID, existingMetadata.SessionID)
   856→	newCommitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, authorName, authorEmail)
   857→	if err != nil {
   858→		return err
   859→	}
   860→
   861→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   862→	newRef := plumbing.NewHashReference(refName, newCommitHash)
   863→	if err := s.repo.Storer.SetReference(newRef); err != nil {
   864→		return fmt.Errorf("failed to set branch reference: %w", err)
   865→	}
   866→
   867→	return nil
   868→}
