   870→// ensureSessionsBranch ensures the entire/sessions branch exists.
   871→func (s *GitStore) ensureSessionsBranch() error {
   872→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   873→	_, err := s.repo.Reference(refName, true)
   874→	if err == nil {
   875→		return nil // Branch exists
   876→	}
   877→
   878→	// Create orphan branch with empty tree
   879→	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
   880→	if err != nil {
   881→		return err
   882→	}
   883→
   884→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
   885→	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
   886→	if err != nil {
   887→		return err
   888→	}
   889→
   890→	newRef := plumbing.NewHashReference(refName, commitHash)
   891→	if err := s.repo.Storer.SetReference(newRef); err != nil {
   892→		return fmt.Errorf("failed to set branch reference: %w", err)
   893→	}
   894→	return nil
   895→}
