   918→// CreateBlobFromContent creates a blob object from in-memory content.
   919→// Exported for use by strategy package (session_test.go)
   920→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
   921→	obj := repo.Storer.NewEncodedObject()
   922→	obj.SetType(plumbing.BlobObject)
   923→	obj.SetSize(int64(len(content)))
   924→
   925→	writer, err := obj.Writer()
   926→	if err != nil {
   927→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
   928→	}
   929→
   930→	_, err = writer.Write(content)
   931→	if err != nil {
   932→		_ = writer.Close()
   933→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
   934→	}
   935→	if err := writer.Close(); err != nil {
   936→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
   937→	}
   938→
   939→	hash, err := repo.Storer.SetEncodedObject(obj)
   940→	if err != nil {
   941→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
   942→	}
   943→	return hash, nil
   944→}
