   946→// copyMetadataDir copies all files from a directory to the checkpoint path.
   947→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
   948→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
   949→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
   950→		if err != nil {
   951→			return err
   952→		}
   953→		if info.IsDir() {
   954→			return nil
   955→		}
   956→
   957→		// Skip symlinks to prevent reading files outside the metadata directory.
   958→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
   959→		// then be captured in the checkpoint and stored in git history.
   960→		if info.Mode()&os.ModeSymlink != 0 {
   961→			return nil
   962→		}
   963→
   964→		// Get relative path within metadata dir
   965→		relPath, err := filepath.Rel(metadataDir, path)
   966→		if err != nil {
   967→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
   968→		}
   969→
   970→		// Prevent path traversal via symlinks pointing outside the metadata dir
   971→		if strings.HasPrefix(relPath, "..") {
   972→			return fmt.Errorf("path traversal detected: %s", relPath)
   973→		}
   974→
   975→		// Create blob from file
   976→		blobHash, mode, err := createBlobFromFile(s.repo, path)
   977→		if err != nil {
   978→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
   979→		}
   980→
   981→		// Store at checkpoint path
   982→		fullPath := basePath + relPath
   983→		entries[fullPath] = object.TreeEntry{
   984→			Name: fullPath,
   985→			Mode: mode,
   986→			Hash: blobHash,
   987→		}
   988→
   989→		return nil
   990→	})
   991→	if err != nil {
   992→		return fmt.Errorf("failed to walk metadata directory: %w", err)
   993→	}
   994→	return nil
   995→}
