   997→// getGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
   998→func getGitAuthorFromRepo(repo *git.Repository) (name, email string) {
   999→	// Get repository config (includes local settings)
  1000→	cfg, err := repo.Config()
  1001→	if err == nil {
  1002→		name = cfg.User.Name
  1003→		email = cfg.User.Email
  1004→	}
  1005→
  1006→	// Provide sensible defaults if git user is not configured
  1007→	if name == "" {
  1008→		name = "Unknown"
  1009→	}
  1010→	if email == "" {
  1011→		email = "unknown@local"
  1012→	}
