  1017→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
  1018→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
  1019→// The agentType is used for reassembling chunks in the correct format.
  1020→func readTranscriptFromTree(tree *object.Tree, agentType agent.AgentType) ([]byte, error) {
  1021→	// Collect all transcript-related files
  1022→	var chunkFiles []string
  1023→	var hasBaseFile bool
  1024→
  1025→	for _, entry := range tree.Entries {
  1026→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
  1027→			hasBaseFile = true
  1028→		}
  1029→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
  1030→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
  1031→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
  1032→			if idx > 0 {
  1033→				chunkFiles = append(chunkFiles, entry.Name)
  1034→			}
  1035→		}
  1036→	}
  1037→
  1038→	// If we have chunk files, read and reassemble them
  1039→	if len(chunkFiles) > 0 {
  1040→		// Sort chunk files by index
  1041→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
  1042→
  1043→		// Check if base file should be included as chunk 0.
  1044→		// NOTE: This assumes the chunking convention where the unsuffixed file
  1045→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
  1046→		if hasBaseFile {
  1047→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
  1048→		}
  1049→
  1050→		var chunks [][]byte
  1051→		for _, chunkFile := range chunkFiles {
  1052→			file, err := tree.File(chunkFile)
  1053→			if err != nil {
  1054→				logging.Warn(context.Background(), "failed to read transcript chunk file from tree",
  1055→					slog.String("chunk_file", chunkFile),
  1056→					slog.String("error", err.Error()),
  1057→				)
  1058→				continue
  1059→			}
  1060→			content, err := file.Contents()
  1061→			if err != nil {
  1062→				logging.Warn(context.Background(), "failed to read transcript chunk contents",
  1063→					slog.String("chunk_file", chunkFile),
  1064→					slog.String("error", err.Error()),
  1065→				)
  1066→				continue
  1067→			}
  1068→			chunks = append(chunks, []byte(content))
  1069→		}
  1070→
  1071→		if len(chunks) > 0 {
  1072→			result, err := agent.ReassembleTranscript(chunks, agentType)
  1073→			if err != nil {
  1074→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
  1075→			}
  1076→			return result, nil
  1077→		}
  1078→	}
  1079→
  1080→	// Fall back to reading base file (non-chunked or backwards compatibility)
  1081→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
  1082→		if content, err := file.Contents(); err == nil {
  1083→			return []byte(content), nil
  1084→		}
  1085→	}
  1086→
  1087→	// Try legacy filename
  1088→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
  1089→		if content, err := file.Contents(); err == nil {
  1090→			return []byte(content), nil
  1091→		}
  1092→	}
  1093→
  1094→	return nil, nil
  1095→}
