    24→// GetSessionInfo returns the current session info.
    25→func (s *ManualCommitStrategy) GetSessionInfo() (*SessionInfo, error) {
    26→	repo, err := OpenRepository()
    27→	if err != nil {
    28→		return nil, fmt.Errorf("failed to open git repository: %w", err)
    29→	}
    30→
    31→	// Check if we're on a shadow branch
    32→	head, err := repo.Head()
    33→	if err != nil {
    34→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
    35→	}
    36→
    37→	if head.Name().IsBranch() {
    38→		branchName := head.Name().Short()
    39→		if strings.HasPrefix(branchName, shadowBranchPrefix) {
    40→			return nil, ErrNoSession
    41→		}
    42→	}
    43→
    44→	// Find sessions for current HEAD
    45→	sessions, err := s.findSessionsForCommit(head.Hash().String())
    46→	if err != nil || len(sessions) == 0 {
    47→		return nil, ErrNoSession
    48→	}
    49→
    50→	// Return info for most recent session
    51→	state := sessions[0]
    52→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
    53→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
    54→
    55→	info := &SessionInfo{
    56→		SessionID: state.SessionID,
    57→		Reference: shadowBranchName,
    58→	}
    59→
    60→	if ref, err := repo.Reference(refName, true); err == nil {
    61→		info.CommitHash = ref.Hash().String()
    62→	}
    63→
    64→	return info, nil
    65→}
