    96→// GetSessionContext returns the context.md content for a session.
    97→// For manual-commit strategy, reads from the entire/sessions branch using sharded paths.
    98→func (s *ManualCommitStrategy) GetSessionContext(sessionID string) string {
    99→	// Find a checkpoint for this session
   100→	checkpoints, err := s.getCheckpointsForSession(sessionID)
   101→	if err != nil || len(checkpoints) == 0 {
   102→		return ""
   103→	}
   104→
   105→	// Use the most recent checkpoint
   106→	sort.Slice(checkpoints, func(i, j int) bool {
   107→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
   108→	})
   109→	checkpointID := checkpoints[0].CheckpointID
   110→
   111→	repo, err := OpenRepository()
   112→	if err != nil {
   113→		return ""
   114→	}
   115→
   116→	// Get the sessions branch
   117→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   118→	ref, err := repo.Reference(refName, true)
   119→	if err != nil {
   120→		return ""
   121→	}
   122→
   123→	commit, err := repo.CommitObject(ref.Hash())
   124→	if err != nil {
   125→		return ""
   126→	}
   127→
   128→	tree, err := commit.Tree()
   129→	if err != nil {
   130→		return ""
   131→	}
   132→
   133→	// Context.md is at <sharded-path>/context.md
   134→	contextPath := paths.CheckpointPath(checkpointID) + "/" + paths.ContextFileName
   135→	file, err := tree.File(contextPath)
   136→	if err != nil {
   137→		return ""
   138→	}
   139→	content, err := file.Contents()
   140→	if err != nil {
   141→		return ""
   142→	}
   143→	return content
   144→}
