   155→// GetAdditionalSessions implements SessionSource interface.
   156→// Returns active sessions from .git/entire-sessions/ that haven't yet been condensed.
   157→func (s *ManualCommitStrategy) GetAdditionalSessions() ([]*Session, error) {
   158→	activeStates, err := s.listAllSessionStates()
   159→	if err != nil {
   160→		return nil, fmt.Errorf("failed to list session states: %w", err)
   161→	}
   162→
   163→	if len(activeStates) == 0 {
   164→		return nil, nil
   165→	}
   166→
   167→	var sessions []*Session
   168→	for _, state := range activeStates {
   169→		session := &Session{
   170→			ID:          state.SessionID,
   171→			Description: NoDescription,
   172→			Strategy:    StrategyNameManualCommit,
   173→			StartTime:   state.StartedAt,
   174→		}
   175→
   176→		// Try to get description from shadow branch
   177→		if description := s.getDescriptionFromShadowBranch(state.SessionID, state.BaseCommit, state.WorktreeID); description != "" {
   178→			session.Description = description
   179→		}
   180→
   181→		sessions = append(sessions, session)
   182→	}
   183→
   184→	return sessions, nil
   185→}
