   187→// getDescriptionFromShadowBranch reads the session description from the shadow branch.
   188→// sessionID is expected to be an Entire session ID (already date-prefixed like "2026-01-12-abc123").
   189→func (s *ManualCommitStrategy) getDescriptionFromShadowBranch(sessionID, baseCommit, worktreeID string) string {
   190→	repo, err := OpenRepository()
   191→	if err != nil {
   192→		return ""
   193→	}
   194→
   195→	shadowBranchName := getShadowBranchNameForCommit(baseCommit, worktreeID)
   196→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
   197→	ref, err := repo.Reference(refName, true)
   198→	if err != nil {
   199→		return ""
   200→	}
   201→
   202→	commit, err := repo.CommitObject(ref.Hash())
   203→	if err != nil {
   204→		return ""
   205→	}
   206→
   207→	tree, err := commit.Tree()
   208→	if err != nil {
   209→		return ""
   210→	}
   211→
   212→	// Use SessionMetadataDirFromEntireID since sessionID is already an Entire session ID
   213→	// (with date prefix like "2026-01-12-abc123")
   214→	metadataDir := paths.SessionMetadataDirFromEntireID(sessionID)
   215→	return getSessionDescriptionFromTree(tree, metadataDir)
   216→}
