    35→func TestCopyMetadataDir_SkipsSymlinks(t *testing.T) {
    36→	// Create a temp directory for the test
    37→	tempDir := t.TempDir()
    38→
    39→	// Initialize a git repository
    40→	repo, err := git.PlainInit(tempDir, false)
    41→	if err != nil {
    42→		t.Fatalf("failed to init git repo: %v", err)
    43→	}
    44→
    45→	// Create metadata directory structure
    46→	metadataDir := filepath.Join(tempDir, "metadata")
    47→	if err := os.MkdirAll(metadataDir, 0755); err != nil {
    48→		t.Fatalf("failed to create metadata dir: %v", err)
    49→	}
    50→
    51→	// Create a regular file that should be included
    52→	regularFile := filepath.Join(metadataDir, "regular.txt")
    53→	if err := os.WriteFile(regularFile, []byte("regular content"), 0644); err != nil {
    54→		t.Fatalf("failed to create regular file: %v", err)
    55→	}
    56→
    57→	// Create a sensitive file outside the metadata directory
    58→	sensitiveFile := filepath.Join(tempDir, "sensitive.txt")
    59→	if err := os.WriteFile(sensitiveFile, []byte("SECRET DATA"), 0644); err != nil {
    60→		t.Fatalf("failed to create sensitive file: %v", err)
    61→	}
    62→
    63→	// Create a symlink inside metadata directory pointing to the sensitive file
    64→	symlinkPath := filepath.Join(metadataDir, "sneaky-link")
    65→	if err := os.Symlink(sensitiveFile, symlinkPath); err != nil {
    66→		t.Fatalf("failed to create symlink: %v", err)
    67→	}
    68→
    69→	// Create GitStore and call copyMetadataDir
    70→	store := NewGitStore(repo)
    71→	entries := make(map[string]object.TreeEntry)
    72→
    73→	err = store.copyMetadataDir(metadataDir, "checkpoint/", entries)
    74→	if err != nil {
    75→		t.Fatalf("copyMetadataDir failed: %v", err)
    76→	}
    77→
    78→	// Verify regular file was included
    79→	if _, ok := entries["checkpoint/regular.txt"]; !ok {
    80→		t.Error("regular.txt should be included in entries")
    81→	}
    82→
    83→	// Verify symlink was NOT included (security fix)
    84→	if _, ok := entries["checkpoint/sneaky-link"]; ok {
    85→		t.Error("symlink should NOT be included in entries - this would allow reading files outside the metadata directory")
    86→	}
    87→
    88→	// Verify the correct number of entries
    89→	if len(entries) != 1 {
    90→		t.Errorf("expected 1 entry, got %d", len(entries))
    91→	}
    92→}
