// TestWriteCommitted_NewFormat_SingleSession verifies that a single session
// is written to subdirectory 0/ with a CheckpointSummary at root.
func TestWriteCommitted_NewFormat_SingleSession(t *testing.T) {
	repo, _ := setupBranchTestRepo(t)
	store := NewGitStore(repo)
	checkpointID := id.MustCheckpointID("f0e1d2c3b4a5")

	// Write a checkpoint with initial attribution and token usage
	tokenUsage := &agent.TokenUsage{
		InputTokens:         100,
		CacheCreationTokens: 1000,
		CacheReadTokens:     50000,
		OutputTokens:        200,
		APICallCount:        10,
	}
	attribution := &InitialAttribution{
		AgentLines:      50,
		HumanAdded:      10,
		TotalCommitted:  60,
		AgentPercentage: 83.33,
	}

	err := store.WriteCommitted(context.Background(), WriteCommittedOptions{
		CheckpointID:       checkpointID,
		SessionID:          "session-1",
		Strategy:           "manual-commit",
		Branch:             "feature/test",
		Agent:              agent.AgentTypeClaudeCode,
		Transcript:         []byte(`{"test": "transcript"}`),
		Prompts:            []string{"First prompt", "Second prompt"},
		Context:            []byte("# Context content"),
		FilesTouched:       []string{"file1.go", "file2.go"},
		CheckpointsCount:   5,
		TokenUsage:         tokenUsage,
		InitialAttribution: attribution,
		AuthorName:         "Test Author",
		AuthorEmail:        "test@example.com",
	})
	if err != nil {
		t.Fatalf("WriteCommitted() error = %v", err)
	}

	// Get the tree for verification
	tree := getCheckpointTree(t, repo, checkpointID)

	// Verify root metadata.json is a CheckpointSummary (not CommittedMetadata)
	rootMetadata := readRootMetadata(t, tree)

	// CheckpointSummary should have these aggregated fields
	if rootMetadata.CheckpointID != checkpointID {
		t.Errorf("root metadata.CheckpointID = %v, want %v", rootMetadata.CheckpointID, checkpointID)
	}
	if rootMetadata.Strategy != "manual-commit" {
		t.Errorf("root metadata.Strategy = %q, want %q", rootMetadata.Strategy, "manual-commit")
	}
	if rootMetadata.Branch != "feature/test" {
		t.Errorf("root metadata.Branch = %q, want %q", rootMetadata.Branch, "feature/test")
	}
	if rootMetadata.SessionCount != 1 {
		t.Errorf("root metadata.SessionCount = %d, want 1", rootMetadata.SessionCount)
	}
	if len(rootMetadata.SessionIDs) != 1 || rootMetadata.SessionIDs[0] != "session-1" {
		t.Errorf("root metadata.SessionIDs = %v, want [session-1]", rootMetadata.SessionIDs)
	}
	if rootMetadata.CheckpointsCount != 5 {
		t.Errorf("root metadata.CheckpointsCount = %d, want 5", rootMetadata.CheckpointsCount)
	}
	if len(rootMetadata.FilesTouched) != 2 {
		t.Errorf("root metadata.FilesTouched length = %d, want 2", len(rootMetadata.FilesTouched))
	}
	if len(rootMetadata.Agents) != 1 || rootMetadata.Agents[0] != agent.AgentTypeClaudeCode {
		t.Errorf("root metadata.Agents = %v, want [Claude Code]", rootMetadata.Agents)
	}

	// Verify token usage is aggregated at root
	if rootMetadata.TokenUsage == nil {
		t.Fatal("root metadata.TokenUsage should not be nil")
	}
	if rootMetadata.TokenUsage.InputTokens != 100 {
		t.Errorf("root metadata.TokenUsage.InputTokens = %d, want 100", rootMetadata.TokenUsage.InputTokens)
	}

	// Verify sessions map exists with correct paths
	if len(rootMetadata.Sessions) != 1 {
		t.Errorf("root metadata.Sessions length = %d, want 1", len(rootMetadata.Sessions))
	}
	session1Paths, ok := rootMetadata.Sessions["session-1"]
	if !ok {
		t.Fatal("root metadata.Sessions should contain 'session-1'")
	}
	if session1Paths.Metadata != "0/metadata.json" {
		t.Errorf("session1Paths.Metadata = %q, want %q", session1Paths.Metadata, "0/metadata.json")
	}
	if session1Paths.Transcript != "0/full.jsonl" {
		t.Errorf("session1Paths.Transcript = %q, want %q", session1Paths.Transcript, "0/full.jsonl")
	}

	// Verify session files are in subdirectory 0/
	sessionTree, err := tree.Tree("0")
	if err != nil {
		t.Fatalf("session subdirectory 0/ not found: %v", err)
	}

	// Verify session-level metadata.json exists and contains initial_attribution
	sessionMetadata := readSessionMetadataFromTree(t, sessionTree)
	if sessionMetadata.SessionID != "session-1" {
		t.Errorf("session metadata.SessionID = %q, want %q", sessionMetadata.SessionID, "session-1")
	}
	if sessionMetadata.InitialAttribution == nil {
		t.Error("session metadata.InitialAttribution should not be nil")
	}
	if sessionMetadata.InitialAttribution != nil && sessionMetadata.InitialAttribution.AgentLines != 50 {
		t.Errorf("session metadata.InitialAttribution.AgentLines = %d, want 50", sessionMetadata.InitialAttribution.AgentLines)
	}

	// Verify transcript is in 0/full.jsonl
	if _, err := sessionTree.File(paths.TranscriptFileName); err != nil {
		t.Errorf("transcript file not found in 0/: %v", err)
	}

	// Verify prompt is in 0/prompt.txt
	if _, err := sessionTree.File(paths.PromptFileName); err != nil {
		t.Errorf("prompt file not found in 0/: %v", err)
	}

	// Verify context is in 0/context.md
	if _, err := sessionTree.File(paths.ContextFileName); err != nil {
		t.Errorf("context file not found in 0/: %v", err)
	}

	// Verify NO files at root level (except metadata.json)
	if _, err := tree.File(paths.TranscriptFileName); err == nil {
		t.Error("transcript file should NOT be at root level")
	}
	if _, err := tree.File(paths.PromptFileName); err == nil {
		t.Error("prompt file should NOT be at root level")
	}
}

// TestWriteCommitted_NewFormat_MultiSession verifies that multiple sessions
// are written to numbered subdirectories with aggregated stats at root.
func TestWriteCommitted_NewFormat_MultiSession(t *testing.T) {
	repo, _ := setupBranchTestRepo(t)
	store := NewGitStore(repo)
	checkpointID := id.MustCheckpointID("a1b2c3d4e5f6")

	// First session with Gemini
	err := store.WriteCommitted(context.Background(), WriteCommittedOptions{
		CheckpointID:     checkpointID,
		SessionID:        "session-gemini",
		Strategy:         "manual-commit",
		Branch:           "main",
		Agent:            agent.AgentTypeGemini,
		Transcript:       []byte(`{"agent": "gemini"}`),
		FilesTouched:     []string{"file1.go"},
		CheckpointsCount: 3,
		TokenUsage: &agent.TokenUsage{
			InputTokens:  100,
			OutputTokens: 50,
			APICallCount: 5,
		},
		AuthorName:  "Test Author",
		AuthorEmail: "test@example.com",
	})
	if err != nil {
		t.Fatalf("WriteCommitted() first session error = %v", err)
	}

	// Second session with Claude Code (same checkpoint ID triggers aggregation)
	err = store.WriteCommitted(context.Background(), WriteCommittedOptions{
		CheckpointID:     checkpointID,
		SessionID:        "session-claude",
		Strategy:         "manual-commit",
		Branch:           "main",
		Agent:            agent.AgentTypeClaudeCode,
		Transcript:       []byte(`{"agent": "claude"}`),
		FilesTouched:     []string{"file2.go", "file3.go"},
		CheckpointsCount: 7,
		TokenUsage: &agent.TokenUsage{
			InputTokens:  200,
			OutputTokens: 100,
			APICallCount: 8,
		},
		AuthorName:  "Test Author",
		AuthorEmail: "test@example.com",
	})
	if err != nil {
		t.Fatalf("WriteCommitted() second session error = %v", err)
	}

	// Get the tree for verification
	tree := getCheckpointTree(t, repo, checkpointID)

	// Verify root metadata aggregation
	rootMetadata := readRootMetadata(t, tree)

	// Session count should be 2
	if rootMetadata.SessionCount != 2 {
		t.Errorf("root metadata.SessionCount = %d, want 2", rootMetadata.SessionCount)
	}

	// SessionIDs should contain both
	if len(rootMetadata.SessionIDs) != 2 {
		t.Errorf("root metadata.SessionIDs length = %d, want 2", len(rootMetadata.SessionIDs))
	}

	// CheckpointsCount should be sum (3 + 7 = 10)
	if rootMetadata.CheckpointsCount != 10 {
		t.Errorf("root metadata.CheckpointsCount = %d, want 10", rootMetadata.CheckpointsCount)
	}

	// FilesTouched should be union (file1.go, file2.go, file3.go)
	if len(rootMetadata.FilesTouched) != 3 {
		t.Errorf("root metadata.FilesTouched length = %d, want 3", len(rootMetadata.FilesTouched))
	}

	// Agents should contain both (deduplicated)
	if len(rootMetadata.Agents) != 2 {
		t.Errorf("root metadata.Agents length = %d, want 2", len(rootMetadata.Agents))
	}

	// TokenUsage should be summed
	if rootMetadata.TokenUsage == nil {
		t.Fatal("root metadata.TokenUsage should not be nil")
	}
	if rootMetadata.TokenUsage.InputTokens != 300 { // 100 + 200
		t.Errorf("root metadata.TokenUsage.InputTokens = %d, want 300", rootMetadata.TokenUsage.InputTokens)
	}
	if rootMetadata.TokenUsage.OutputTokens != 150 { // 50 + 100
		t.Errorf("root metadata.TokenUsage.OutputTokens = %d, want 150", rootMetadata.TokenUsage.OutputTokens)
	}
	if rootMetadata.TokenUsage.APICallCount != 13 { // 5 + 8
		t.Errorf("root metadata.TokenUsage.APICallCount = %d, want 13", rootMetadata.TokenUsage.APICallCount)
	}

	// Verify sessions map has both sessions
	if len(rootMetadata.Sessions) != 2 {
		t.Errorf("root metadata.Sessions length = %d, want 2", len(rootMetadata.Sessions))
	}

	// First session should be in 0/
	session0Paths, ok := rootMetadata.Sessions["session-gemini"]
	if !ok {
		t.Fatal("root metadata.Sessions should contain 'session-gemini'")
	}
	if session0Paths.Metadata != "0/metadata.json" {
		t.Errorf("session0Paths.Metadata = %q, want %q", session0Paths.Metadata, "0/metadata.json")
	}

	// Second session should be in 1/
	session1Paths, ok := rootMetadata.Sessions["session-claude"]
	if !ok {
		t.Fatal("root metadata.Sessions should contain 'session-claude'")
	}
	if session1Paths.Metadata != "1/metadata.json" {
		t.Errorf("session1Paths.Metadata = %q, want %q", session1Paths.Metadata, "1/metadata.json")
	}

	// Verify both session subdirectories exist
	if _, err := tree.Tree("0"); err != nil {
		t.Errorf("session subdirectory 0/ not found: %v", err)
	}
	if _, err := tree.Tree("1"); err != nil {
		t.Errorf("session subdirectory 1/ not found: %v", err)
	}
}

