// TestReadCommitted_NewFormat verifies that ReadCommitted correctly reads
// data from the new storage format using the sessions map.
func TestReadCommitted_NewFormat(t *testing.T) {
	repo, _ := setupBranchTestRepo(t)
	store := NewGitStore(repo)
	checkpointID := id.MustCheckpointID("c3d4e5f6a7b8")

	// Write two sessions
	err := store.WriteCommitted(context.Background(), WriteCommittedOptions{
		CheckpointID:     checkpointID,
		SessionID:        "session-1",
		Strategy:         "manual-commit",
		Agent:            agent.AgentTypeGemini,
		Transcript:       []byte(`{"session": 1}`),
		Prompts:          []string{"Prompt 1"},
		Context:          []byte("Context 1"),
		FilesTouched:     []string{"file1.go"},
		CheckpointsCount: 3,
		AuthorName:       "Test",
		AuthorEmail:      "test@test.com",
	})
	if err != nil {
		t.Fatalf("WriteCommitted() first session error = %v", err)
	}

	err = store.WriteCommitted(context.Background(), WriteCommittedOptions{
		CheckpointID:     checkpointID,
		SessionID:        "session-2",
		Strategy:         "manual-commit",
		Agent:            agent.AgentTypeClaudeCode,
		Transcript:       []byte(`{"session": 2}`),
		Prompts:          []string{"Prompt 2"},
		Context:          []byte("Context 2"),
		FilesTouched:     []string{"file2.go"},
		CheckpointsCount: 5,
		AuthorName:       "Test",
		AuthorEmail:      "test@test.com",
	})
	if err != nil {
		t.Fatalf("WriteCommitted() second session error = %v", err)
	}

	// Read back the checkpoint
	result, err := store.ReadCommitted(context.Background(), checkpointID)
	if err != nil {
		t.Fatalf("ReadCommitted() error = %v", err)
	}
	if result == nil {
		t.Fatal("ReadCommitted() returned nil")
	}

	// Verify metadata reflects aggregated data
	if result.Metadata.SessionCount != 2 {
		t.Errorf("result.Metadata.SessionCount = %d, want 2", result.Metadata.SessionCount)
	}
	if result.Metadata.CheckpointsCount != 8 { // 3 + 5
		t.Errorf("result.Metadata.CheckpointsCount = %d, want 8", result.Metadata.CheckpointsCount)
	}

	// Transcript should be the latest session (session-2)
	if !strings.Contains(string(result.Transcript), `"session": 2`) {
		t.Errorf("result.Transcript should contain session 2 data, got: %s", string(result.Transcript))
	}

	// Prompts should be from latest session
	if !strings.Contains(result.Prompts, "Prompt 2") {
		t.Errorf("result.Prompts should contain 'Prompt 2', got: %s", result.Prompts)
	}

	// Context should be from latest session
	if result.Context != "Context 2" {
		t.Errorf("result.Context = %q, want %q", result.Context, "Context 2")
	}

	// ArchivedSessions should contain session-1
	if len(result.ArchivedSessions) != 1 {
		t.Errorf("result.ArchivedSessions length = %d, want 1", len(result.ArchivedSessions))
	}
	if len(result.ArchivedSessions) > 0 {
		if result.ArchivedSessions[0].SessionID != "session-1" {
			t.Errorf("ArchivedSessions[0].SessionID = %q, want %q", result.ArchivedSessions[0].SessionID, "session-1")
		}
		if !strings.Contains(string(result.ArchivedSessions[0].Transcript), `"session": 1`) {
			t.Errorf("ArchivedSessions[0].Transcript should contain session 1 data")
		}
	}
}

// Helper functions for new format tests

// getCheckpointTree returns the tree for a checkpoint on the sessions branch.
func getCheckpointTree(t *testing.T, repo *git.Repository, checkpointID id.CheckpointID) *object.Tree {
	t.Helper()

	ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		t.Fatalf("failed to get metadata branch reference: %v", err)
	}

	commit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		t.Fatalf("failed to get commit object: %v", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		t.Fatalf("failed to get tree: %v", err)
	}

	checkpointTree, err := tree.Tree(checkpointID.Path())
	if err != nil {
		t.Fatalf("failed to get checkpoint tree at %s: %v", checkpointID.Path(), err)
	}

	return checkpointTree
}

// readRootMetadata reads the CheckpointSummary from root metadata.json.
func readRootMetadata(t *testing.T, tree *object.Tree) *CheckpointSummary {
	t.Helper()

	file, err := tree.File(paths.MetadataFileName)
	if err != nil {
		t.Fatalf("failed to find root metadata.json: %v", err)
	}

	content, err := file.Contents()
	if err != nil {
		t.Fatalf("failed to read root metadata.json: %v", err)
	}

	var summary CheckpointSummary
	if err := json.Unmarshal([]byte(content), &summary); err != nil {
		t.Fatalf("failed to parse root metadata.json as CheckpointSummary: %v", err)
	}

	return &summary
}

// readSessionMetadataFromTree reads CommittedMetadata from a session subdirectory tree.
func readSessionMetadataFromTree(t *testing.T, sessionTree *object.Tree) *CommittedMetadata {
	t.Helper()

	file, err := sessionTree.File(paths.MetadataFileName)
	if err != nil {
		t.Fatalf("failed to find session metadata.json: %v", err)
	}

	content, err := file.Contents()
	if err != nil {
		t.Fatalf("failed to read session metadata.json: %v", err)
	}

	var metadata CommittedMetadata
	if err := json.Unmarshal([]byte(content), &metadata); err != nil {
		t.Fatalf("failed to parse session metadata.json: %v", err)
	}

	return &metadata
}

