// readCheckpointMetadata reads checkpoint metadata from the metadata branch.
// It reads the root CheckpointSummary and converts it to CommittedMetadata for compatibility.
// To get session-specific fields (like Agent), it also reads from the latest session's metadata.
func readCheckpointMetadata(t *testing.T, repo *git.Repository, checkpointID id.CheckpointID) CommittedMetadata {
	t.Helper()

	ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		t.Fatalf("failed to get metadata branch reference: %v", err)
	}

	commit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		t.Fatalf("failed to get commit object: %v", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		t.Fatalf("failed to get tree: %v", err)
	}

	checkpointTree, err := tree.Tree(checkpointID.Path())
	if err != nil {
		t.Fatalf("failed to get checkpoint tree: %v", err)
	}

	// Read root metadata.json as CheckpointSummary
	metadataFile, err := checkpointTree.File(paths.MetadataFileName)
	if err != nil {
		t.Fatalf("failed to find metadata.json: %v", err)
	}

	content, err := metadataFile.Contents()
	if err != nil {
		t.Fatalf("failed to read metadata.json: %v", err)
	}

	var summary CheckpointSummary
	if err := json.Unmarshal([]byte(content), &summary); err != nil {
		t.Fatalf("failed to parse metadata.json as CheckpointSummary: %v", err)
	}

	// Convert CheckpointSummary to CommittedMetadata
	metadata := CommittedMetadata{
		CheckpointID:     summary.CheckpointID,
		Strategy:         summary.Strategy,
		CreatedAt:        summary.CreatedAt,
		Branch:           summary.Branch,
		CheckpointsCount: summary.CheckpointsCount,
		FilesTouched:     summary.FilesTouched,
		SessionCount:     summary.SessionCount,
		SessionIDs:       summary.SessionIDs,
		Agents:           summary.Agents,
		TokenUsage:       summary.TokenUsage,
	}

	// Set Agent from Agents array
	if len(summary.Agents) > 0 {
		metadata.Agent = summary.Agents[0]
	}

	// Set SessionID to latest session
	if len(summary.SessionIDs) > 0 {
		metadata.SessionID = summary.SessionIDs[len(summary.SessionIDs)-1]
	}

	return metadata
}

