// GetSessionContext returns the context.md content for a session.
// For manual-commit strategy, reads from the entire/sessions branch using the sessions map.
func (s *ManualCommitStrategy) GetSessionContext(sessionID string) string {
	// Find a checkpoint for this session
	checkpoints, err := s.getCheckpointsForSession(sessionID)
	if err != nil || len(checkpoints) == 0 {
		return ""
	}

	// Use the most recent checkpoint
	sort.Slice(checkpoints, func(i, j int) bool {
		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
	})
	checkpointID := checkpoints[0].CheckpointID

	repo, err := OpenRepository()
	if err != nil {
		return ""
	}

	// Get the sessions branch
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref, err := repo.Reference(refName, true)
	if err != nil {
		return ""
	}

	commit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		return ""
	}

	tree, err := commit.Tree()
	if err != nil {
		return ""
	}

	// Get checkpoint tree
	checkpointPath := paths.CheckpointPath(checkpointID)
	checkpointTree, err := tree.Tree(checkpointPath)
	if err != nil {
		return ""
	}

	// Read root metadata to find session's context path from sessions map
	metadataFile, err := checkpointTree.File(paths.MetadataFileName)
	if err != nil {
		return ""
	}

	metadataContent, err := metadataFile.Contents()
	if err != nil {
		return ""
	}

	var summary checkpoint.CheckpointSummary
	if err := json.Unmarshal([]byte(metadataContent), &summary); err != nil {
		return ""
	}

	// Look up context path from sessions map
	sessionPaths, ok := summary.Sessions[sessionID]
	if !ok {
		// Fall back to latest session if specific session not found
		if summary.SessionCount > 0 {
			latestIndex := summary.SessionCount - 1
			sessionPaths = checkpoint.SessionFilePaths{
				Context: fmt.Sprintf("%d/%s", latestIndex, paths.ContextFileName),
			}
		} else {
			return ""
		}
	}

	// Read context from the session's subdirectory
	if sessionPaths.Context == "" {
		return ""
	}
	file, err := checkpointTree.File(sessionPaths.Context)
	if err != nil {
		return ""
	}
	content, err := file.Contents()
	if err != nil {
		return ""
	}
	return content
}

