func readMetadataFromTree[T any](t *testing.T, tree *object.Tree, desc string) *T {
	t.Helper()

	file, err := tree.File(paths.MetadataFileName)
	if err != nil {
		t.Fatalf("failed to find %s metadata.json: %v", desc, err)
	}

	content, err := file.Contents()
	if err != nil {
		t.Fatalf("failed to read %s metadata.json: %v", desc, err)
	}

	var result T
	if err := json.Unmarshal([]byte(content), &result); err != nil {
		t.Fatalf("failed to parse %s metadata.json: %v", desc, err)
	}

	return &result
}

